import { ref, onUnmounted } from 'vue';
import { notify } from 'src/components/notifications/notify';
import { useTranslate } from '@tolgee/vue';
import FulltextSettingsApiService, {
  ReindexProgressResponse,
  DocumentStatsResponse,
  FulltextTemplateVersions,
} from 'src/services/settings/FulltextSettingsApiService';

export interface UseReindexProgressOptions {
  /**
   * Suppress the success toast emitted when the SSE `complete` event
   * arrives. Used by the Dashboard SSE consumer (quick-search.vue),
   * which only needs the live state updates (docStats, streamStatus)
   * but not the toast — the toast belongs to user-triggered reindex
   * flows on /settings/fulltext, where the user just clicked a Reindex
   * button and expects feedback.
   */
  silent?: boolean;
}

export function useReindexProgress(
  apiService: FulltextSettingsApiService,
  options: UseReindexProgressOptions = {},
) {
  const { silent = false } = options;
  const { t } = useTranslate();

  const docStats = ref<DocumentStatsResponse['stats'] | null>(null);
  const templateVersions = ref<FulltextTemplateVersions | null>(null);
  const initialLoading = ref(true);
  const refreshing = ref(false);
  const lastUpdated = ref<Date | null>(null);

  // Bug-2026-05-01 (Ruiz Foods incident): user couldn't tell if indexing
  // was actually progressing on stage when ERP-bulk was hogging the
  // worker pool. Counters changed at 0.1 docs/min (vs expected ~16) and
  // the static "X / Y indexed" display didn't make the slowdown visible.
  // Track a rolling-window velocity (docs indexed / minute) plus an ETA
  // so the user can see at a glance "fertig in 30 min" or "stuck —
  // 0.1/min, ETA 4 days".
  //
  // Implementation: ring buffer of the last N (timestamp, total_indexed)
  // samples. Rolling rate = (last.indexed - first.indexed) / window_min.
  // Window adjusts to whatever sample range is currently in buffer
  // (60s minimum so transient OS-refresh races don't produce wild rates).
  type VelocitySample = { ts: number; total: number };
  const VELOCITY_WINDOW_MS = 5 * 60 * 1000; // 5-min rolling window
  const VELOCITY_MIN_SPAN_MS = 60 * 1000; // need ≥60s of samples for a stable rate
  const VELOCITY_MAX_SAMPLES = 20;
  const velocitySamples = ref<VelocitySample[]>([]);
  const indexDocsPerMinute = ref<number | null>(null);
  const indexETA = ref<Date | null>(null);
  // Scope: last `loadDocumentStats` outcome only. The polling fallback,
  // `checkActiveReindex`, and `loadSyncDiagnostics` still log to console
  // without setting this ref — they're transient and the UI shouldn't
  // show a red state for them.
  const error = ref<Error | null>(null);

  const docReindexing = ref(false);
  const docReindexMode = ref<'sync' | 'full' | null>(null);
  const reindexProgress = ref<ReindexProgressResponse | null>(null);
  const syncDiagnostics = ref<import('src/services/settings/FulltextSettingsApiService').SyncDiagnosticsResponse | null>(null);
  const diagnosticsLoading = ref(false);

  // Bug 2026-05-02: persistent failed-state. Previously
  // `handleProgressComplete` fired `notify.error` on every failure event
  // and nulled `reindexProgress` after 3s — but the backend caches
  // `__cached_on` and replays the same failed snapshot on every SSE
  // tick, so the user got a "(x367)" toast aggregation while the UI
  // still claimed "Index healthy". Stash the last failure here so the
  // settings page can render a persistent banner with a Retry action.
  // Cleared by `dismissLastFailure()` (banner X-button) or by
  // `reindexDocuments()` (a new run starts) or by a successful complete.
  const lastFailure = ref<ReindexProgressResponse['progress'] | null>(null);
  const dismissLastFailure = () => {
    lastFailure.value = null;
  };

  // Internal refs for polling/SSE cleanup
  const progressPollInterval = ref<ReturnType<typeof setInterval> | null>(null);
  const progressEventSource = ref<EventSource | null>(null);
  const docIndexingPollInterval = ref<ReturnType<typeof setInterval> | null>(null);
  let documentStatsRequest: Promise<void> | null = null;
  let reindexProgressRequest: Promise<ReindexProgressResponse> | null = null;

  // Bug-2026-04-29: SSE-Sichtbarkeit. Ohne diesen state hatte der User
  // KEIN UI-Signal ob der Stream lebt — bei stillen Fehlern (Token
  // expired, CORS, Backend-hang) sah die Seite identisch aus zur
  // "alles fein, nur idle" Variante. Jetzt kann eine Pill je nach
  // streamStatus zeigen ob die Verbindung aktiv ist.
  //
  // Lifecycle:
  //   'connecting'   → initial / nach reconnect, vor erstem 'progress' event
  //   'live'         → SSE offen UND mindestens ein event empfangen
  //   'reconnecting' → 'error' event mit readyState=CONNECTING (auto-retry)
  //   'fallback'     → SSE permanent geschlossen, polling läuft
  //   'error'        → kein Connect möglich, polling auch tot
  const streamStatus = ref<
    'connecting' | 'live' | 'reconnecting' | 'fallback' | 'error'
  >('connecting');
  const streamLastEventAt = ref<Date | null>(null);

  const loadDocumentStats = async () => {
    if (documentStatsRequest) {
      return documentStatsRequest;
    }

    // Stale-while-revalidate: never wipe docStats on refresh, only on
    // success. `initialLoading` flips to false the first time we either
    // succeed OR fail — either way we stop showing the skeleton.
    if (docStats.value !== null) {
      refreshing.value = true;
    }

    documentStatsRequest = (async () => {
      try {
        const response = await apiService.getDocumentStats();
        if (response.success) {
          docStats.value = response.stats;
          templateVersions.value = response.template_versions ?? null;
          lastUpdated.value = new Date();
          error.value = null;
        }
      } catch (err) {
        error.value = err instanceof Error ? err : new Error(String(err));
        console.error('Failed to load document stats:', err);
      } finally {
        initialLoading.value = false;
        refreshing.value = false;
        documentStatsRequest = null;
      }
    })();

    return documentStatsRequest;
  };

  const getReindexProgressSingleFlight = async () => {
    if (reindexProgressRequest) {
      return null;
    }

    reindexProgressRequest = apiService.getReindexProgress();
    try {
      return await reindexProgressRequest;
    } finally {
      reindexProgressRequest = null;
    }
  };

  const loadSyncDiagnostics = async () => {
    diagnosticsLoading.value = true;
    try {
      const response = await apiService.getSyncDiagnostics(10);
      if (response.success) {
        syncDiagnostics.value = response;
      }
    } catch (err) {
      console.error('Failed to load sync diagnostics:', err);
    } finally {
      diagnosticsLoading.value = false;
    }
  };

  // Heartbeat poll runs ALONGSIDE SSE as a safety net: SSE can stay
  // connected but miss the final `complete` event if the server closes
  // the stream abruptly, or if a fast reindex finishes before SSE
  // subscribes. The heartbeat verifies `active` every 5s and resolves
  // the reindex state if the server reports it's no longer running.
  const heartbeatInterval = ref<ReturnType<typeof setInterval> | null>(null);

  const stopProgressPoll = () => {
    if (progressEventSource.value) {
      progressEventSource.value.close();
      progressEventSource.value = null;
    }
    if (progressPollInterval.value) {
      clearInterval(progressPollInterval.value);
      progressPollInterval.value = null;
    }
    if (heartbeatInterval.value) {
      clearInterval(heartbeatInterval.value);
      heartbeatInterval.value = null;
    }
  };

  const startHeartbeatPoll = () => {
    if (heartbeatInterval.value) return;
    heartbeatInterval.value = setInterval(async () => {
      if (!docReindexing.value) return;
      try {
        const response = await getReindexProgressSingleFlight();
        if (!response) return;
        if (!response.active && docReindexing.value) {
          // Server reports no active reindex — treat as completion.
          stopProgressPoll();
          handleProgressComplete(
            response.progress ?? {
              total: 0,
              processed: 0,
              indexed: 0,
              failed: 0,
              current_batch: 0,
              status: 'completed',
              percent_complete: 100,
              updated_at: new Date().toISOString(),
              errors: [],
            },
          );
          await loadDocumentStats();
        }
      } catch (err) {
        console.warn('Heartbeat poll failed:', err);
      }
    }, 5000);
  };

  const handleProgressComplete = (progress: ReindexProgressResponse['progress']) => {
    docReindexing.value = false;
    docReindexMode.value = null;

    const indexed = progress?.indexed ?? 0;
    const failed = progress?.failed ?? 0;

    if (progress?.status === 'completed') {
      if (!silent) {
        notify.success(`${t.value('fulltext_indexing_complete') || 'Indexing complete'}: ${indexed} ${t.value('fulltext_indexed_label') || 'indexed'}, ${failed} ${t.value('fulltext_failed_label') || 'failed'}`);
      }
      // Successful completion clears any stale failure banner.
      lastFailure.value = null;
    } else {
      // Bug 2026-05-02: stash the failed snapshot once into `lastFailure`
      // so DocumentIndexingSection.vue can render a persistent banner
      // with [Retry] / [Dismiss]. NO `notify.error` here — the backend
      // re-emits the cached failed state on every SSE tick (see
      // `__cached_on` in executer.get_reindex_progress) which used to
      // produce a "(x367)" toast aggregation. We only update the
      // banner when `updated_at` actually changed so a stable cached
      // failure doesn't re-trigger any UI work.
      if (
        progress &&
        progress.updated_at &&
        progress.updated_at !== lastFailure.value?.updated_at
      ) {
        lastFailure.value = progress;
      } else if (!progress) {
        lastFailure.value = null;
      }
    }

    setTimeout(() => {
      reindexProgress.value = null;
    }, 3000);
  };

  const startProgressPollFallback = () => {
    if (progressPollInterval.value) return;

    progressPollInterval.value = setInterval(async () => {
      try {
        const response = await getReindexProgressSingleFlight();
        if (!response) return;
        reindexProgress.value = response;
        await loadDocumentStats();
        // Polling-Fallback: jeder erfolgreiche Tick ist ein Lebenszeichen.
        // streamStatus bleibt 'fallback' (statt 'live') damit User sieht
        // dass es nicht der bevorzugte SSE-Pfad ist.
        if (streamStatus.value !== 'fallback') {
          streamStatus.value = 'fallback';
        }
        streamLastEventAt.value = new Date();

        if (response.progress?.status === 'completed' || response.progress?.status === 'failed') {
          stopProgressPoll();
          handleProgressComplete(response.progress);
        } else if (!response.active && docReindexing.value) {
          // Server says no reindex active but we still think we are —
          // we missed the final event. Treat as completion.
          stopProgressPoll();
          handleProgressComplete(
            response.progress ?? {
              total: 0,
              processed: 0,
              indexed: 0,
              failed: 0,
              current_batch: 0,
              status: 'completed',
              percent_complete: 100,
              updated_at: new Date().toISOString(),
              errors: [],
            },
          );
        }
      } catch (err) {
        console.error('Failed to poll reindex progress:', err);
      }
    }, 2000);
  };

  const recomputeVelocity = (totalIndexed: number, missing: number) => {
    const now = Date.now();
    const samples = velocitySamples.value;

    // Append, then evict by age + cap.
    samples.push({ ts: now, total: totalIndexed });
    const cutoff = now - VELOCITY_WINDOW_MS;
    while (samples.length > 0 && samples[0].ts < cutoff) samples.shift();
    while (samples.length > VELOCITY_MAX_SAMPLES) samples.shift();

    if (samples.length < 2) {
      indexDocsPerMinute.value = null;
      indexETA.value = null;
      return;
    }
    const first = samples[0];
    const last = samples[samples.length - 1];
    const spanMs = last.ts - first.ts;
    if (spanMs < VELOCITY_MIN_SPAN_MS) {
      // Don't publish a rate yet — the first 60s would otherwise show
      // wildly fluctuating "1200/min" numbers from a single delta.
      return;
    }
    const deltaIndexed = last.total - first.total;
    if (deltaIndexed <= 0) {
      // Counter didn't move — explicit zero so the UI can render
      // "stuck (0/min)" rather than the previous stale rate.
      indexDocsPerMinute.value = 0;
      indexETA.value = null;
      return;
    }
    const ratePerMin = (deltaIndexed / spanMs) * 60 * 1000;
    indexDocsPerMinute.value = Math.round(ratePerMin * 10) / 10;
    if (missing > 0 && ratePerMin > 0) {
      const minutesRemaining = missing / ratePerMin;
      indexETA.value = new Date(now + minutesRemaining * 60 * 1000);
    } else {
      indexETA.value = null;
    }
  };

  const resetVelocity = () => {
    velocitySamples.value = [];
    indexDocsPerMinute.value = null;
    indexETA.value = null;
  };

  const applySnapshot = (data: any) => {
    if (!data) return;
    if (data.progress !== undefined) {
      reindexProgress.value = {
        success: true,
        org_id: '',
        progress: data.progress,
        active: data.active,
      };
    }
    // The backend pushes `document_stats` (new field) plus a `stats`
    // alias for backwards-compat. Accept either, prefer the new one.
    const docStatsPayload = data.document_stats ?? data.stats;
    if (docStatsPayload) {
      docStats.value = docStatsPayload;
    }
    if (data.template_versions !== undefined) {
      templateVersions.value = data.template_versions ?? null;
    }

    // Bug 2026-05-05: use OpenSearch coverage counters as the source of
    // truth for velocity. `progress.processed` is a task-local Redis
    // snapshot; chained/old Celery tasks can keep it flat or rewrite it
    // out of order while the index is visibly growing. That produced the
    // false "Indexing stuck — 0 docs/min" state even though worker logs
    // showed completed chunks. For the document-first sync we can infer
    // the active phase from stats:
    //   1. missing text docs > 0  => track total_indexed
    //   2. text complete          => track with_vector for vector catch-up
    // Idle dashboards still use total_indexed for ad-hoc inserts.
    const wasActive = docReindexing.value;
    const isActive = Boolean(data.active);
    if (isActive !== wasActive) {
      resetVelocity();
    }

    const inDb = Number(docStatsPayload?.in_database ?? 0);
    if (isActive && docStatsPayload) {
      const totalIndexed = Number(docStatsPayload.total_indexed ?? 0);
      const withVector = Number(docStatsPayload.with_vector ?? 0);
      const missingText = Math.max(0, inDb - totalIndexed);
      if (missingText > 0) {
        recomputeVelocity(totalIndexed, missingText);
      } else {
        const missingVector = Math.max(0, inDb - withVector);
        recomputeVelocity(withVector, missingVector);
      }
    } else if (docStatsPayload) {
      const total = Number(docStatsPayload.total_indexed ?? 0);
      const missing = Math.max(0, inDb - total);
      recomputeVelocity(total, missing);
    }
    docReindexing.value = isActive;
    docReindexMode.value = isActive
      ? data.progress?.status === 'running'
        ? 'sync'
        : null
      : null;
  };

  const startProgressSSE = async () => {
    stopProgressPoll();
    streamStatus.value = 'connecting';

    // Start the safety heartbeat regardless of SSE outcome. It only
    // pings every 5s and is cheap; it catches the edge case where SSE
    // connects but the backend never sends the final complete event
    // (connection drop, fast reindex, etc).
    startHeartbeatPoll();

    try {
      const url = await apiService.getIndexStatusStreamURL();
      const es = new EventSource(url);
      progressEventSource.value = es;

      es.addEventListener('open', () => {
        streamStatus.value = 'live';
        streamLastEventAt.value = new Date();
      });

      es.addEventListener('progress', (event: MessageEvent) => {
        try {
          applySnapshot(JSON.parse(event.data));
          streamStatus.value = 'live';
          streamLastEventAt.value = new Date();
        } catch (err) {
          console.error('Failed to parse SSE progress event:', err);
        }
      });

      // Bug-2026-04-29: backend (router.py:_index_status_event_generator)
      // emits an `idle` event every 30s when the snapshot is unchanged so
      // the UI gets a steady "I'm alive" heartbeat — without it the user
      // saw zero events for an idle org and thought the stream was dead.
      es.addEventListener('idle', () => {
        streamStatus.value = 'live';
        streamLastEventAt.value = new Date();
      });

      es.addEventListener('complete', (event: MessageEvent) => {
        try {
          const data = JSON.parse(event.data);
          applySnapshot(data);
          handleProgressComplete(data.progress);
          streamStatus.value = 'live';
          streamLastEventAt.value = new Date();
        } catch (err) {
          console.error('Failed to parse SSE complete event:', err);
        }
        // Stream stays open: backend keeps pushing idle stats so the
        // page stays live without re-opening a new EventSource.
      });

      es.addEventListener('timeout', () => {
        // Older backends still emit timeout to close the stream after
        // 5 minutes idle; reopen so the user still gets live updates.
        streamStatus.value = 'reconnecting';
        stopProgressPoll();
        startProgressSSE();
      });

      es.addEventListener('error', () => {
        // EventSource auto-reconnects on transient drops. We only
        // hard-fall-back to polling if the connection is permanently
        // dead (readyState === CLOSED).
        if (es.readyState === EventSource.CLOSED) {
          console.warn('SSE permanently closed, falling back to polling');
          streamStatus.value = 'fallback';
          stopProgressPoll();
          startProgressPollFallback();
        } else {
          // readyState === CONNECTING means the browser is auto-retrying
          streamStatus.value = 'reconnecting';
        }
      });
    } catch (err) {
      console.warn('Failed to start SSE, falling back to polling:', err);
      streamStatus.value = 'fallback';
      startProgressPollFallback();
    }
  };

  const startProgressPoll = () => {
    startProgressSSE();
  };

  const startStatusStream = () => {
    startProgressSSE();
  };

  const stopDocIndexingPoll = () => {
    if (docIndexingPollInterval.value) {
      clearInterval(docIndexingPollInterval.value);
      docIndexingPollInterval.value = null;
    }
  };

  const checkActiveReindex = async () => {
    // SSE delivers status whether or not a reindex is active, so the
    // legacy "open SSE only when active" gate is gone. Just open the
    // stream — the backend will tell us if a reindex is running.
    startStatusStream();
  };

  const reindexDocuments = async (mode: 'sync' | 'full') => {
    // A user-triggered run clears any stale failure banner from the
    // previous attempt — they took action, banner served its purpose.
    lastFailure.value = null;
    docReindexing.value = true;
    docReindexMode.value = mode;

    reindexProgress.value = {
      success: true,
      org_id: '',
      progress: {
        total: docStats.value?.in_database ?? 0,
        processed: 0,
        indexed: 0,
        failed: 0,
        current_batch: 0,
        status: 'running',
        percent_complete: 0,
        updated_at: new Date().toISOString(),
        errors: [],
      },
      active: true,
    };

    startProgressPoll();

    apiService
      .rebuildDocumentIndex(mode, true)
      .then((response) => {
        if (response.success) {
          notify.info(t.value('fulltext_indexing_started') || 'Indexing started in background...', { duration: 2000 });
        } else {
          stopProgressPoll();
          notify.error(response.message || t.value('fulltext_reindex_failed'));
          docReindexing.value = false;
          docReindexMode.value = null;
          reindexProgress.value = null;
        }
      })
      .catch((err: any) => {
        stopProgressPoll();
        notify.error(err.message || t.value('fulltext_reindex_failed'));
        docReindexing.value = false;
        docReindexMode.value = null;
        reindexProgress.value = null;
      });
  };

  const cleanup = () => {
    stopProgressPoll();
    stopDocIndexingPoll();
  };

  onUnmounted(cleanup);

  return {
    docStats,
    templateVersions,
    initialLoading,
    refreshing,
    lastUpdated,
    error,
    docReindexing,
    docReindexMode,
    reindexProgress,
    syncDiagnostics,
    diagnosticsLoading,
    // Bug-2026-04-29: SSE-Sichtbarkeit für Settings-Page
    streamStatus,
    streamLastEventAt,
    // Bug-2026-05-01: indexing velocity + ETA so user can tell at a
    // glance whether the index is actually progressing or stuck.
    indexDocsPerMinute,
    indexETA,
    // Bug-2026-05-02: persistent failed-state banner driver
    lastFailure,
    dismissLastFailure,
    loadDocumentStats,
    loadSyncDiagnostics,
    checkActiveReindex,
    startStatusStream,
    reindexDocuments,
    cleanup,
  };
}
